from langchain_core.tools import tool
import math, random

@tool
def calculator(expression: str) -> str:
    """Evaluates a math expression. Use for any arithmetic or math questions."""
    try:
        result = eval(expression, {"__builtins__": {}}, {"math": math})
        return f"Result: {result}"
    except Exception as e:
        return f"Error: {e}"

@tool
def weather_tool(city: str) -> str:
    """Gets current weather for a city. Use when user asks about weather."""
    # Simulated - replace with real API
    temps = {"london": "15°C cloudy", "new york": "22°C sunny", "tokyo": "28°C humid"}
    return temps.get(city.lower(), f"{city}: 20°C partly cloudy")

@tool
def web_search(query: str) -> str:
    """Searches the web for information. Use for factual/current information questions."""
    # Simulated - replace with real search API
    return f"Search results for '{query}': [Relevant info about {query} found]"

@tool
def unit_converter(value: float, from_unit: str, to_unit: str) -> str:
    """Converts units (km/miles, celsius/fahrenheit, kg/lbs). Use for unit conversion."""
    conversions = {
        ("km", "miles"): lambda x: x * 0.621371,
        ("miles", "km"): lambda x: x * 1.60934,
        ("celsius", "fahrenheit"): lambda x: x * 9/5 + 32,
        ("fahrenheit", "celsius"): lambda x: (x - 32) * 5/9,
        ("kg", "lbs"): lambda x: x * 2.20462,
        ("lbs", "kg"): lambda x: x * 0.453592,
    }
    key = (from_unit.lower(), to_unit.lower())
    if key in conversions:
        result = conversions[key](value)
        return f"{value} {from_unit} = {result:.2f} {to_unit}"
    return f"Conversion from {from_unit} to {to_unit} not supported"

@tool
def summarizer(text: str) -> str:
    """Summarizes long text into key points. Use when user wants a summary."""
    words = text.split()
    if len(words) > 20:
        return f"Summary: {' '.join(words[:15])}... [{len(words)} words condensed]"
    return f"Summary: {text}"

ALL_TOOLS = [calculator, weather_tool, web_search, unit_converter, summarizer]
